const b = $input.first().json.body || $input.first().json;
const f = b.fields || {};
const ist = new Date(b.createdAt || Date.now()).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
const details = Object.entries(f).filter(([k]) => !['area','property_area','property_type','country'].includes(k)).map(([k,v]) => k + ': ' + v).join(' | ');
return [{ json: {
  'Timestamp (IST)': ist, 'Form type': b.form_type, 'Source page': b.source_page, 'Name': b.name, 'Phone': b.phone,
  'Country': f.country || '', 'Property area': f.area || f.property_area || f.location || '', 'Property type': f.property_type || '',
  'Details': details, 'Referrer': b.referrer || '', 'UTM source': (b.utm||{}).source || '', 'UTM medium': (b.utm||{}).medium || '', 'UTM campaign': (b.utm||{}).campaign || '',
  'Enquiry ID': b.id, 'Status': 'New', 'Owner': '', 'Next follow-up': '', 'Notes': '' } }];
